int with_read_stream(const char *path, int (*body)(FILE *, void *), void *ctx) {
    FILE *f = fopen(path, "r");              /* setup */
    int rc = -1;
    if (!f) return -1;
    if (body(f, ctx) != 0) goto cleanup;      /* body, once */
    rc = 0;
cleanup:
    if (fclose(f) != 0 && rc == 0) rc = -1;   /* teardown on every path */
    return rc;
}

