static void unlock(void *arg) { pthread_mutex_unlock((pthread_mutex_t *)arg); }

static void *worker(void *arg) {
    pthread_mutex_t *m = arg;
    pthread_mutex_lock(m);
    pthread_cleanup_push(unlock, m);   /* setup registers the teardown */
    do_work();                         /* body: cancellation runs unlock() */
    pthread_cleanup_pop(1);            /* teardown for the normal path */
    return NULL;
}
